package com.bank.statics;

import java.math.BigDecimal;
import java.util.logging.*;

// main is static so the JVM can call it WITHOUT creating a StaticDemo instance.
public class StaticDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        TransferService service = new TransferService(repo);

        // static method called on the CLASS, no object needed
        BigDecimal fee = FeeCalculator.standardFee(new BigDecimal("50000"));
        log.info(() -> "Standard fee on 50000 = Rs." + fee);

        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        service.transfer("CUR3001", "SAV2001", new BigDecimal("10000"));

        // static variable shared across ALL TransferService instances
        log.info(() -> "Total transfers system-wide = " + TransferService.getTotalTransfers());
    }
}

// ─── Would be Account.java in a real project ───
class Account {
    private final String accountId;
    private BigDecimal balance;
    Account(String id, BigDecimal bal) { accountId=id; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── Would be AccountRepository.java in a real project ───
class AccountRepository {
    private final java.util.Map<String, Account> db = new java.util.HashMap<>();
    AccountRepository() {
        db.put("SAV2001", new Account("SAV2001", new BigDecimal("1000000.00")));
        db.put("CUR3001", new Account("CUR3001", new BigDecimal("250000.00")));
    }
    Account findById(String id) { return db.get(id); }
}

// ─── Would be FeeCalculator.java in a real project ───
// Stateless utility: all methods static, no instance needed.
class FeeCalculator {
    static final BigDecimal RATE = new BigDecimal("0.0002"); // 0.02%
    static BigDecimal standardFee(BigDecimal amount) {
        return amount.multiply(RATE).setScale(2, java.math.RoundingMode.HALF_EVEN);
    }
}

// ─── Would be TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");
    // static VARIABLE: one shared counter for the whole class
    private static int totalTransfers = 0;
    private static final java.util.Map<String, String> BRANCH_CODES = new java.util.HashMap<>();

    // static BLOCK: runs ONCE when the class is loaded
    static {
        BRANCH_CODES.put("SAV2001", "MUM-001");
        BRANCH_CODES.put("CUR3001", "MUM-002");
        log.info("Static block: branch codes loaded once at class load");
    }

    private final AccountRepository repo;
    TransferService(AccountRepository repo) { this.repo = repo; }

    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);
        from.debit(amount);
        to.credit(amount);
        totalTransfers++; // mutates shared static state
        log.info(() -> "Transfer " + amount + " " + fromId + "(" + BRANCH_CODES.get(fromId)
                        + ") -> " + toId + "(" + BRANCH_CODES.get(toId) + ")");
    }

    static int getTotalTransfers() { return totalTransfers; }
}
